#!/usr/bin/env bash
set -euo pipefail
ROOT=$(git rev-parse --show-toplevel);EXP="$ROOT/experiments/0014-pocket-fp-onnx-qnn-htp";CANON="$EXP/.local/canonical-benchmark";STAGE="$EXP/.local/canonical-benchmark-stage";ORT="$ROOT/experiments/0010-supertonic-qnn-htp-feasibility/.local/ort-v1.27.1-qnn-2.49.0-android-arm64/Release";INC="$ROOT/experiments/0010-supertonic-qnn-htp-feasibility/.local/onnxruntime-v1.27.1-source/include/onnxruntime/core/session";NDK=${ANDROID_NDK_ROOT:-/home/moritz/opt/android-sdk/ndk/26.2.11394342};QAIRT=${QAIRT_SDK_ROOT:-/home/moritz/opt/qairt/2.49.0.260730};CC="$NDK/toolchains/llvm/prebuilt/linux-x86_64/bin/aarch64-linux-android27-clang++";ASSETS="$EXP/work/canonical-benchmark/assets";OLD_ASSETS="$EXP/work/quality-recovery/alba-assets";MANIFEST="$EXP/work/canonical-benchmark/stage-sha256.txt"
for f in "$CANON/text/text_conditioner-text64.onnx" "$CANON/qnn-flow/flow_lm_prefill_text64.onnx" "$CANON/qnn-flow/flow_lm_ar_bos1.onnx" "$CANON/qnn-flow/flow_lm_ar_latent1.onnx" "$ASSETS/canonical-token-ids-64.i64" "$ASSETS/numpy-randomstate-seed0-temp0p3-292x32.f32" "$OLD_ASSETS/alba-flow-cache-v1.f32";do [[ -f $f ]]||{ echo "missing $f" >&2;exit 2;};done
rm -rf "$STAGE";mkdir -p "$STAGE/model" "$STAGE/lib" "$STAGE/assets";"$CC" -std=c++17 -O2 -fPIE -pie -I"$INC" "$EXP/tools/pocket_alba_static_benchmark_runner.cc" -L"$ORT" -lonnxruntime -Wl,-rpath,'$ORIGIN/lib' -o "$STAGE/pocket_alba_static_benchmark_runner";cp "$CANON/text/text_conditioner-text64.onnx" "$STAGE/model/text_conditioner.onnx";cp "$CANON/qnn-flow/flow_lm_prefill_text64.onnx" "$STAGE/model/flow_prefill_text64.onnx";cp "$CANON/qnn-flow/flow_lm_ar_bos1.onnx" "$STAGE/model/flow_ar_bos1.onnx";cp "$CANON/qnn-flow/flow_lm_ar_latent1.onnx" "$STAGE/model/flow_ar_latent1.onnx";cp "$EXP/.local/static-optimized/flow_lm_flow-flow1.onnx" "$STAGE/model/flow.onnx";for n in 12 6 1;do cp "$EXP/.local/qnn-v2/mimi_decoder-decoder$n.onnx" "$STAGE/model/mimi_decoder$n.onnx";done;cp "$ASSETS/canonical-token-ids-64.i64" "$ASSETS/numpy-randomstate-seed0-temp0p3-292x32.f32" "$OLD_ASSETS/alba-flow-cache-v1.f32" "$STAGE/assets/";cp "$ORT/libonnxruntime.so" "$STAGE/lib/";cp "$QAIRT/lib/aarch64-android/"{libQnnHtp.so,libQnnHtpPrepare.so,libQnnHtpV73Stub.so,libQnnSystem.so} "$STAGE/lib/";cp "$QAIRT/lib/hexagon-v73/unsigned/libQnnHtpV73Skel.so" "$STAGE/lib/";cp "$NDK/toolchains/llvm/prebuilt/linux-x86_64/sysroot/usr/lib/aarch64-linux-android/libc++_shared.so" "$STAGE/lib/";(cd "$STAGE"&&find . -type f -exec sha256sum {} +|sort)>"$MANIFEST";du -sh "$STAGE";echo "$MANIFEST"
